package com.gvc.ravenloftcastleapi.controller.campana;

import com.gvc.ravenloftcastleapi.dto.campana.CampanaCreateDTO;
import com.gvc.ravenloftcastleapi.dto.campana.CampanaDetalleDTO;
import com.gvc.ravenloftcastleapi.dto.campana.CodigoInvitacionDTO;
import com.gvc.ravenloftcastleapi.dto.campana.CampanaUpdateDTO;
import com.gvc.ravenloftcastleapi.dto.mision.MisionResumenDTO;
import com.gvc.ravenloftcastleapi.service.CampanaService;
import com.gvc.ravenloftcastleapi.service.JoinService;
import com.gvc.ravenloftcastleapi.dto.personaje.PersonajeResponseDTO;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/campanas")
@RequiredArgsConstructor
public class CampanaController {

    private final CampanaService campanaService;
    private final JoinService joinService;

    @PostMapping
    public ResponseEntity<CampanaDetalleDTO> crearCampana(@Valid @RequestBody CampanaCreateDTO dto) {
        return ResponseEntity.status(HttpStatus.CREATED).body(campanaService.crearCampana(dto));
    }

    @PutMapping("/{id}/codigo-invitacion")
    public ResponseEntity<String> actualizarCodigoInvitacion(@PathVariable Long id, @Valid @RequestBody CodigoInvitacionDTO dto) {
        String nuevoCodigo = campanaService.actualizarCodigoInvitacion(id, dto.getCodigo());
        return ResponseEntity.ok(nuevoCodigo);
    }


    @GetMapping("/{id}")
    public ResponseEntity<CampanaDetalleDTO> obtenerCampana(@PathVariable Long id) {
        return ResponseEntity.ok(campanaService.obtenerCampanaPorId(id));
    }

    @PutMapping("/{id}")
    public ResponseEntity<CampanaDetalleDTO> actualizarCampana(@PathVariable Long id, @Valid @RequestBody CampanaUpdateDTO dto) {
        return ResponseEntity.ok(campanaService.actualizarCampana(id, dto));
    }

    @GetMapping
    public ResponseEntity<List<CampanaDetalleDTO>> obtenerCampanasPublicas() {
        return ResponseEntity.ok(campanaService.listarCampanasPublicas());
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> eliminarCampana(@PathVariable Long id) {
        campanaService.eliminarCampana(id);
        return ResponseEntity.noContent().build();
    }

    @PostMapping("/{id}/salir")
    public ResponseEntity<String> salirDeCampana(@PathVariable Long id) {
        String email = SecurityContextHolder.getContext().getAuthentication().getName();
        joinService.salirDeCampana(email, id);
        return ResponseEntity.ok("Has salido de la campaña correctamente");
    }

    @GetMapping("/{id}/jugadores")
    public ResponseEntity<List<PersonajeResponseDTO>> listarJugadoresDeCampana(@PathVariable Long id) {
        return ResponseEntity.ok(campanaService.listarJugadoresDeCampana(id));
    }

    @GetMapping("/{id}/misiones")
    public ResponseEntity<List<MisionResumenDTO>> listarMisionesDeCampana(@PathVariable Long id) {
        return ResponseEntity.ok(campanaService.listarMisionesDeCampana(id));
    }
}

package com.gvc.ravenloftcastleapi.controller.campana;

import com.gvc.ravenloftcastleapi.dto.campana.CampanaCreateDTO;
import com.gvc.ravenloftcastleapi.dto.campana.CampanaDetalleDTO;
import com.gvc.ravenloftcastleapi.dto.campana.CodigoInvitacionDTO;
import com.gvc.ravenloftcastleapi.dto.campana.CampanaUpdateDTO;
import com.gvc.ravenloftcastleapi.dto.mision.MisionResumenDTO;
import com.gvc.ravenloftcastleapi.dto.enemigo.CampanaEnemigoDTO;
import com.gvc.ravenloftcastleapi.service.CampanaService;
import com.gvc.ravenloftcastleapi.service.JoinService;
import com.gvc.ravenloftcastleapi.dto.personaje.PersonajeResponseDTO;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/campanas")
@RequiredArgsConstructor
public class CampanaController {

    private final CampanaService campanaService;
    private final JoinService joinService;

    @PostMapping
    public ResponseEntity<CampanaDetalleDTO> crearCampana(@Valid @RequestBody CampanaCreateDTO dto) {
        return ResponseEntity.status(HttpStatus.CREATED).body(campanaService.crearCampana(dto));
    }

    @PutMapping("/{id}/codigo-invitacion")
    public ResponseEntity<String> actualizarCodigoInvitacion(@PathVariable Long id, @Valid @RequestBody CodigoInvitacionDTO dto) {
        String nuevoCodigo = campanaService.actualizarCodigoInvitacion(id, dto.getCodigo());
        return ResponseEntity.ok(nuevoCodigo);
    }


    @GetMapping("/{id}")
    public ResponseEntity<CampanaDetalleDTO> obtenerCampana(@PathVariable Long id) {
        return ResponseEntity.ok(campanaService.obtenerCampanaPorId(id));
    }

    @PutMapping("/{id}")
    public ResponseEntity<CampanaDetalleDTO> actualizarCampana(@PathVariable Long id, @Valid @RequestBody CampanaUpdateDTO dto) {
        return ResponseEntity.ok(campanaService.actualizarCampana(id, dto));
    }

    @GetMapping
    public ResponseEntity<List<CampanaDetalleDTO>> obtenerCampanasPublicas() {
        return ResponseEntity.ok(campanaService.listarCampanasPublicas());
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> eliminarCampana(@PathVariable Long id) {
        campanaService.eliminarCampana(id);
        return ResponseEntity.noContent().build();
    }

    @PostMapping("/{id}/salir")
    public ResponseEntity<String> salirDeCampana(@PathVariable Long id) {
        String email = SecurityContextHolder.getContext().getAuthentication().getName();
        joinService.salirDeCampana(email, id);
        return ResponseEntity.ok("Has salido de la campaña correctamente");
    }

    @GetMapping("/{id}/jugadores")
    public ResponseEntity<List<PersonajeResponseDTO>> listarJugadoresDeCampana(@PathVariable Long id) {
        return ResponseEntity.ok(campanaService.listarJugadoresDeCampana(id));
    }

    @GetMapping("/{id}/misiones")
    public ResponseEntity<List<MisionResumenDTO>> listarMisionesDeCampana(@PathVariable Long id) {
        return ResponseEntity.ok(campanaService.listarMisionesDeCampana(id));
    }

    @PostMapping("/{id}/enemigos")
    @PreAuthorize("hasRole('ADMIN')")
    public ResponseEntity<Void> asignarEnemigo(
            @PathVariable Long id,
            @Valid @RequestBody CampanaEnemigoDTO dto) {
        campanaService.asignarEnemigo(id, dto);
        return ResponseEntity.status(HttpStatus.CREATED).build();
    }
}

package com.gvc.ravenloftcastleapi.service;

import com.gvc.ravenloftcastleapi.dto.campana.CampanaCreateDTO;
import com.gvc.ravenloftcastleapi.dto.campana.CampanaDetalleDTO;
import com.gvc.ravenloftcastleapi.dto.mision.MisionResumenDTO;
import com.gvc.ravenloftcastleapi.dto.personaje.PersonajeResponseDTO;
import com.gvc.ravenloftcastleapi.entity.Campana;
import com.gvc.ravenloftcastleapi.entity.CampanaPersonaje;
import com.gvc.ravenloftcastleapi.entity.Mision;
import com.gvc.ravenloftcastleapi.entity.Personaje;
import com.gvc.ravenloftcastleapi.repository.CampanaRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class CampanaService {

    private final CampanaRepository campanaRepository;

    @Transactional
    public CampanaDetalleDTO crearCampana(CampanaCreateDTO dto) {
        String codigoGenerado = UUID.randomUUID().toString();

        Campana nuevaCampana = Campana.builder()
                .nombre(dto.getNombre())
                .descripcion(dto.getDescripcion())
                .fechaCreacion(LocalDate.now())
                .dificultad(dto.getDificultad())
                .nivelMinimo(dto.getNivelMinimo())
                .maxJugadores(dto.getMaxJugadores())
                .sistema(dto.getSistema())
                .active(dto.isActive())
                .nivelAcceso(dto.getNivelAcceso())
                .codigoInvitacion(codigoGenerado)
                .build();

        Campana campanaGuardada = campanaRepository.save(nuevaCampana);
        return mapToDetalleDTO(campanaGuardada);
    }

    @Transactional(readOnly = true)
    public CampanaDetalleDTO obtenerCampanaPorId(Long id) {
        Campana campana = campanaRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Campaña no encontrada"));
        return mapToDetalleDTO(campana);
    }

    @Transactional(readOnly = true)
    public List<CampanaDetalleDTO> listarCampanasPublicas() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        boolean isAdmin = auth != null && auth.getAuthorities().stream()
                .anyMatch(a -> a.getAuthority().equals("ROLE_ADMIN"));

        List<Campana> campanas = campanaRepository.findAll();
        return campanas.stream()
                .filter(campana -> isAdmin || campana.isActive())
                .map(this::mapToDetalleDTO)
                .collect(Collectors.toList());
    }

    @Transactional
    public String actualizarCodigoInvitacion(Long campanaId, String nuevoCodigo) {
        Campana campana = campanaRepository.findById(campanaId)
                .orElseThrow(() -> new RuntimeException("Campaña no encontrada"));

        // Validar si el código ya existe
        if (campanaRepository.existsByCodigoInvitacion(nuevoCodigo)) {
            throw new RuntimeException("El código de invitación ya está en uso");
        }

        campana.setCodigoInvitacion(nuevoCodigo);
        campanaRepository.save(campana);
        return nuevoCodigo;
    }

    private CampanaDetalleDTO mapToDetalleDTO(Campana campana) {
        return CampanaDetalleDTO.builder()
                .id(campana.getId())
                .nombre(campana.getNombre())
                .descripcion(campana.getDescripcion())
                .dificultad(campana.getDificultad())
                .nivelMinimo(campana.getNivelMinimo())
                .maxJugadores(campana.getMaxJugadores())
                .active(campana.isActive())
                .master(null) // TODO: Implementar lógica para obtener el master
                .personajes(Optional.ofNullable(campana.getPersonajes())
                        .orElse(Collections.emptyList())
                        .stream()
                        .map(CampanaPersonaje::getPersonaje)
                        .map(this::mapToPersonajeDTO)
                        .collect(Collectors.toList()))
                .misiones(Optional.ofNullable(campana.getMisiones())
                        .orElse(Collections.emptyList())
                        .stream()
                        .map(this::mapToMisionDTO)
                        .collect(Collectors.toList()))
                .build();
    }

    private PersonajeResponseDTO mapToPersonajeDTO(Personaje personaje) {
        return PersonajeResponseDTO.builder()
                .id(personaje.getId())
                .nombre(personaje.getNombre())
                .clase(personaje.getClase() != null ? personaje.getClase().getNombre() : "Sin Clase")
                .raza(personaje.getRaza() != null ? personaje.getRaza().getNombre() : "Sin Raza")
                .nivel(personaje.getNivel())
                .fuerza(personaje.getFuerza())
                .destreza(personaje.getDestreza())
                .build();
    }

    private MisionResumenDTO mapToMisionDTO(Mision mision) {
        return new MisionResumenDTO(
                mision.getId(),
                mision.getNombre(),
                mision.getDificultad(),
                mision.getXpRecompensa(),
                mision.isCompletada()
        );
    }
}

package com.gvc.ravenloftcastleapi.service;

import com.gvc.ravenloftcastleapi.dto.campana.CampanaCreateDTO;
import com.gvc.ravenloftcastleapi.dto.campana.CampanaDetalleDTO;
import com.gvc.ravenloftcastleapi.dto.mision.MisionResumenDTO;
import com.gvc.ravenloftcastleapi.dto.personaje.PersonajeResponseDTO;
import com.gvc.ravenloftcastleapi.entity.Campana;
import com.gvc.ravenloftcastleapi.entity.CampanaPersonaje;
import com.gvc.ravenloftcastleapi.entity.Mision;
import com.gvc.ravenloftcastleapi.entity.Personaje;
import com.gvc.ravenloftcastleapi.repository.CampanaRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class CampanaService {

    private final CampanaRepository campanaRepository;

    @Transactional
    public CampanaDetalleDTO crearCampana(CampanaCreateDTO dto) {
        String codigoGenerado = UUID.randomUUID().toString();

        Campana nuevaCampana = Campana.builder()
                .nombre(dto.getNombre())
                .descripcion(dto.getDescripcion())
                .fechaCreacion(LocalDate.now())
                .dificultad(dto.getDificultad())
                .nivelMinimo(dto.getNivelMinimo())
                .maxJugadores(dto.getMaxJugadores())
                .sistema(dto.getSistema())
                .active(dto.isActive())
                .nivelAcceso(dto.getNivelAcceso())
                .codigoInvitacion(codigoGenerado)
                .build();

        Campana campanaGuardada = campanaRepository.save(nuevaCampana);
        return mapToDetalleDTO(campanaGuardada);
    }

    @Transactional(readOnly = true)
    public CampanaDetalleDTO obtenerCampanaPorId(Long id) {
        Campana campana = campanaRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Campaña no encontrada"));
        return mapToDetalleDTO(campana);
    }

    @Transactional(readOnly = true)
    public List<CampanaDetalleDTO> listarCampanasPublicas() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        boolean isAdmin = auth != null && auth.getAuthorities().stream()
                .anyMatch(a -> a.getAuthority().equals("ROLE_ADMIN"));

        List<Campana> campanas = campanaRepository.findAll();
        return campanas.stream()
                .filter(campana -> isAdmin || campana.isActive())
                .map(this::mapToDetalleDTO)
                .collect(Collectors.toList());
    }

    @Transactional
    public String actualizarCodigoInvitacion(Long campanaId, String nuevoCodigo) {
        Campana campana = campanaRepository.findById(campanaId)
                .orElseThrow(() -> new RuntimeException("Campaña no encontrada"));

        // Validar si el código ya existe
        if (campanaRepository.existsByCodigoInvitacion(nuevoCodigo)) {
            throw new RuntimeException("El código de invitación ya está en uso");
        }

        campana.setCodigoInvitacion(nuevoCodigo);
        campanaRepository.save(campana);
        return nuevoCodigo;
    }

    @Transactional
    public String generarCodigoInvitacion(Long campanaId) {
        Campana campana = campanaRepository.findById(campanaId)
                .orElseThrow(() -> new RuntimeException("Campaña no encontrada"));

        String nuevoCodigo = UUID.randomUUID().toString();
        // Asegurar unicidad (aunque es muy improbable colisionar con UUID)
        while (campanaRepository.existsByCodigoInvitacion(nuevoCodigo)) {
            nuevoCodigo = UUID.randomUUID().toString();
        }

        campana.setCodigoInvitacion(nuevoCodigo);
        campanaRepository.save(campana);
        return nuevoCodigo;
    }

    private CampanaDetalleDTO mapToDetalleDTO(Campana campana) {
        return CampanaDetalleDTO.builder()
                .id(campana.getId())
                .nombre(campana.getNombre())
                .descripcion(campana.getDescripcion())
                .dificultad(campana.getDificultad())
                .nivelMinimo(campana.getNivelMinimo())
                .maxJugadores(campana.getMaxJugadores())
                .active(campana.isActive())
                .master(null) // TODO: Implementar lógica para obtener el master
                .personajes(Optional.ofNullable(campana.getPersonajes())
                        .orElse(Collections.emptyList())
                        .stream()
                        .map(CampanaPersonaje::getPersonaje)
                        .map(this::mapToPersonajeDTO)
                        .collect(Collectors.toList()))
                .misiones(Optional.ofNullable(campana.getMisiones())
                        .orElse(Collections.emptyList())
                        .stream()
                        .map(this::mapToMisionDTO)
                        .collect(Collectors.toList()))
                .build();
    }

    private PersonajeResponseDTO mapToPersonajeDTO(Personaje personaje) {
        return PersonajeResponseDTO.builder()
                .id(personaje.getId())
                .nombre(personaje.getNombre())
                .clase(personaje.getClase() != null ? personaje.getClase().getNombre() : "Sin Clase")
                .raza(personaje.getRaza() != null ? personaje.getRaza().getNombre() : "Sin Raza")
                .nivel(personaje.getNivel())
                .fuerza(personaje.getFuerza())
                .destreza(personaje.getDestreza())
                .build();
    }

    private MisionResumenDTO mapToMisionDTO(Mision mision) {
        return new MisionResumenDTO(
                mision.getId(),
                mision.getNombre(),
                mision.getDificultad(),
                mision.getXpRecompensa(),
                mision.isCompletada()
        );
    }
}

import { API_URL, authHeaders } from './api';

export interface CampanaRequest {
  nombre: string;
  descripcion: string;
  calcDistancia: string;
  logo: string | null;
  imagen: string | null;
  mapasSeleccionados: number[];
}

export interface CampanaResponse {
  id: number;
  nombre: string;
  descripcion: string;
  calcDistancia: string;
  logo: string | null;
  imagen: string | null;
  masterId: number;
  masterNombre: string;
  mapasSeleccionados: number[];
  dificultad: 'Fácil' | 'Media' | 'Difícil' | 'Épica';
  maxJugadores: number;
  nivelMinimo: number;
  sistema: string;
  active: boolean;
}

export const crearCampana = async (request: CampanaRequest): Promise<CampanaResponse> => {
  const response = await fetch(`${API_URL}/api/campanas`, {
    method: 'POST',
    headers: authHeaders(),
    body: JSON.stringify(request),
  });
  if (!response.ok) {
    throw new Error('Error al crear campaña');
  }
  return response.json();
};

export const obtenerMisCampanas = async (): Promise<CampanaResponse[]> => {
  const response = await fetch(`${API_URL}/api/campanas/mis-campanas`, {
    method: 'GET',
    headers: authHeaders(),
  });
  if (!response.ok) {
    throw new Error('Error al obtener mis campañas');
  }
  return response.json();
};

export const obtenerCampanasActivas = async (): Promise<CampanaResponse[]> => {
  const response = await fetch(`${API_URL}/api/campanas`, {
    method: 'GET',
    headers: authHeaders(),
  });
  if (!response.ok) {
    throw new Error('Error al obtener campañas activas');
  }
  return response.json();
};

export const eliminarCampana = async (id: number): Promise<void> => {
  const response = await fetch(`${API_URL}/api/campanas/${id}`, {
    method: 'DELETE',
    headers: authHeaders(),
  });
  if (!response.ok) {
    throw new Error('Error al eliminar la campaña');
  }
};

